// Vanilla maze game. Reads window.LEVELS (generated by the Bazel build) and
// plays entirely client-side from file://. No dependencies, no fetch.
(function () {
  "use strict";

  var LEVELS = Array.isArray(window.LEVELS) ? window.LEVELS : [];
  var canvas = document.getElementById("maze");
  var ctx = canvas.getContext("2d");
  var levelNameEl = document.getElementById("level-name");
  var keysCountEl = document.getElementById("keys-count");
  var statusEl = document.getElementById("status");
  var stampEl = document.getElementById("build-stamp");

  if (window.BUILD_VERSION) {
    stampEl.textContent = "build: " + window.BUILD_VERSION;
  }

  var COLORS = {
    wall: "#1d2740",
    open: "#0b0f18",
    exit: "#39d98a",
    exitLocked: "#2a4a3c",
    key: "#ffcc4d",
    player: "#5aa9ff",
  };

  var levelIndex = 0;
  var state = null; // { level, player:{x,y}, keys:[{x,y,taken}], tile }

  function loadLevel(i) {
    var level = LEVELS[i];
    if (!level) {
      return;
    }
    var tile = Math.floor(Math.min(480 / level.width, 480 / level.height));
    canvas.width = tile * level.width;
    canvas.height = tile * level.height;
    state = {
      level: level,
      player: { x: level.start[0], y: level.start[1] },
      keys: level.keys.map(function (k) {
        return { x: k[0], y: k[1], taken: false };
      }),
      tile: tile,
    };
    levelNameEl.textContent = level.name || "level " + (i + 1);
    statusEl.textContent = "Grab every key, then reach the exit.";
    draw();
    updateHud();
  }

  function remainingKeys() {
    return state.keys.filter(function (k) {
      return !k.taken;
    }).length;
  }

  function updateHud() {
    var total = state.keys.length;
    keysCountEl.textContent = "keys " + (total - remainingKeys()) + "/" + total;
  }

  function isWall(x, y) {
    var g = state.level.grid;
    if (y < 0 || y >= g.length || x < 0 || x >= g[0].length) {
      return true;
    }
    return g[y][x] === 1;
  }

  function tryMove(dx, dy) {
    if (!state) {
      return;
    }
    var nx = state.player.x + dx;
    var ny = state.player.y + dy;
    if (isWall(nx, ny)) {
      return;
    }
    state.player.x = nx;
    state.player.y = ny;

    state.keys.forEach(function (k) {
      if (!k.taken && k.x === nx && k.y === ny) {
        k.taken = true;
      }
    });
    updateHud();

    var exit = state.level.exit;
    if (nx === exit[0] && ny === exit[1]) {
      if (remainingKeys() === 0) {
        advance();
        return;
      }
      statusEl.textContent = "The exit is locked. " + remainingKeys() + " key(s) left.";
    }
    draw();
  }

  function advance() {
    levelIndex++;
    if (levelIndex >= LEVELS.length) {
      winScreen();
      return;
    }
    statusEl.textContent = "Level clear! Loading next...";
    loadLevel(levelIndex);
  }

  function winScreen() {
    ctx.fillStyle = COLORS.open;
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    ctx.fillStyle = COLORS.exit;
    ctx.font = "bold 22px monospace";
    ctx.textAlign = "center";
    ctx.fillText("You escaped the build graph!", canvas.width / 2, canvas.height / 2);
    levelNameEl.textContent = "complete";
    statusEl.textContent = "All levels cleared. Reload to play again.";
  }

  function draw() {
    var t = state.tile;
    var level = state.level;
    for (var y = 0; y < level.height; y++) {
      for (var x = 0; x < level.width; x++) {
        ctx.fillStyle = isWall(x, y) ? COLORS.wall : COLORS.open;
        ctx.fillRect(x * t, y * t, t, t);
      }
    }

    var exit = level.exit;
    ctx.fillStyle = remainingKeys() === 0 ? COLORS.exit : COLORS.exitLocked;
    ctx.fillRect(exit[0] * t + 2, exit[1] * t + 2, t - 4, t - 4);

    ctx.fillStyle = COLORS.key;
    state.keys.forEach(function (k) {
      if (!k.taken) {
        ctx.beginPath();
        ctx.arc(k.x * t + t / 2, k.y * t + t / 2, Math.max(3, t / 5), 0, Math.PI * 2);
        ctx.fill();
      }
    });

    ctx.fillStyle = COLORS.player;
    ctx.beginPath();
    ctx.arc(
      state.player.x * t + t / 2,
      state.player.y * t + t / 2,
      Math.max(4, t / 3),
      0,
      Math.PI * 2
    );
    ctx.fill();
  }

  var KEYMAP = {
    ArrowUp: [0, -1], KeyW: [0, -1],
    ArrowDown: [0, 1], KeyS: [0, 1],
    ArrowLeft: [-1, 0], KeyA: [-1, 0],
    ArrowRight: [1, 0], KeyD: [1, 0],
  };

  window.addEventListener("keydown", function (e) {
    var move = KEYMAP[e.code];
    if (move) {
      e.preventDefault();
      tryMove(move[0], move[1]);
    }
  });

  if (LEVELS.length === 0) {
    statusEl.textContent = "No levels found. Build //game:site and open its index.html.";
  } else {
    loadLevel(0);
  }
})();
